public class Monster {
    private String name;
    private int leben;
    private int staerke;

    public Monster(String name, int leben, int staerke) {
        this.name = name;
        this.leben = leben;
        this.staerke = staerke;
    }

    public void nimmSchaden(int schaden) {
        leben = leben - schaden;
        if (leben < 0) {
            leben = 0;
        }
    }

    public boolean istBesiegt() {
        return leben < 0;
    }

    public void angreifen(Held h) {
        h.leben = h.leben - staerke;
    }
}

